//! nushell: generated code, and the hooks in `env.nu` and `config.nu`.

use std::env;
use std::path::{Path, PathBuf};
use std::process::Command;

use super::{Dialect, Parts, Shell, home_relative, lines, tool_block};
use crate::Paths;
use crate::config::{Condition, Config};
use crate::template::{self, Seg};

pub struct Nu;

/// The file `tools_check` writes, next to the other generated files.
pub const TOOLS_FILE: &str = "tools.nu";

impl Dialect for Nu {
    fn env(name: &str, value: &str) -> String {
        format!("$env.{name} = {}\n", template_expr(value))
    }

    fn path(prepend: &[&str], append: &[&str]) -> String {
        let list = |l: &[&str]| {
            l.iter()
                .map(|p| template_expr(p))
                .collect::<Vec<_>>()
                .join(" ")
        };
        let mut expr = String::from("$env.PATH | split row (char esep)");
        if !prepend.is_empty() {
            expr.push_str(&format!(" | prepend [{}]", list(prepend)));
        }
        if !append.is_empty() {
            expr.push_str(&format!(" | append [{}]", list(append)));
        }
        format!("$env.PATH = ({expr} | uniq)\n")
    }

    fn alias(name: &str, body: &str) -> String {
        format!("alias {name} = {}\n", body.trim())
    }

    /// nushell parses the body as part of the `alias` command, which also
    /// restricts what it may be (a command call, not a pipeline).
    fn alias_snippet(name: &str, body: &str) -> (String, bool) {
        (Self::alias(name, body), true)
    }

    /// nushell defines aliases while parsing, so an alias inside a runtime
    /// `if` would only exist in that block.
    fn guard(_: &[Condition]) -> Option<(String, String)> {
        None
    }
}

/// A nushell string literal that needs no escaping: `'...'` when possible,
/// otherwise a raw string `r#'...'#` with enough `#`s.
pub fn quote(s: &str) -> String {
    if !s.contains('\'') {
        return format!("'{s}'");
    }
    let mut hashes = String::from("#");
    while s.contains(&format!("'{hashes}")) {
        hashes.push('#');
    }
    format!("r{hashes}'{s}'{hashes}")
}

fn var(name: &str) -> String {
    match name {
        // $env.PATH is a list in nushell; flatten it the way other shells see it.
        "PATH" => "($env.PATH | split row (char esep) | str join (char esep))".into(),
        // nushell doesn't set HOME on Windows. Elsewhere HOME as set, like the
        // other shells; $nu.home-dir would resolve symlinks in it.
        "HOME" if cfg!(windows) => "$nu.home-dir".into(),
        _ => format!("($env.{name}? | default '')"),
    }
}

/// A nushell expression for a template string.
fn template_expr(s: &str) -> String {
    let parts: Vec<String> = template::parse(s)
        .into_iter()
        .map(|seg| match seg {
            Seg::Lit(lit) => quote(&lit),
            Seg::Var(name) => var(&name),
        })
        .collect();
    match parts.len() {
        0 => "''".into(),
        1 => parts.into_iter().next().unwrap(),
        _ => format!("([{}] | str join)", parts.join(" ")),
    }
}

/// A path as a nushell string, `~`-relative where possible.
fn path_str(p: &Path, home: &Path) -> String {
    match home_relative(p, home) {
        Some(rel) => quote(&format!("~/{rel}")),
        None => quote(&p.display().to_string()),
    }
}

/// `tools.nu`: the `[tool]` conditions as nushell code, for the env.nu hook,
/// which runs it in its own scope. It evaluates to the tools found now and
/// the ones `init.nu` was `built` with. Conditions may depend on the env and
/// path entries above them, so those lines are repeated here.
pub fn tools_check(cfg: &Config, built: &[String]) -> String {
    let mut out = String::from(
        "# Generated by shellsync: the [tool] checks for nushell's env.nu hook. Do not edit.\n\
         mut found = []\n",
    );
    out.push_str(&lines::<Nu>(&cfg.entries, Shell::Nu, Parts::ENV));
    for tool in &cfg.tools {
        if tool_block::<Nu>(tool, Shell::Nu, Parts::ALL).is_empty() {
            continue;
        }
        let test: Vec<String> = tool.conditions.iter().map(condition).collect();
        out.push_str(&format!(
            "if {} {{\n  $found = ($found | append {})\n",
            test.join(" and "),
            quote(&tool.name)
        ));
        for line in lines::<Nu>(&tool.entries, Shell::Nu, Parts::ENV).lines() {
            out.push_str(&format!("  {line}\n"));
        }
        out.push_str("}\n");
    }
    let built: Vec<String> = built.iter().map(|t| quote(t)).collect();
    out.push_str(&format!(
        "{{built: [{}], found: $found}}\n",
        built.join(" ")
    ));
    out
}

/// `which` instead of a PATH walk: it is built in and checks the executable
/// bit, also for a path.
fn condition(c: &Condition) -> String {
    match c {
        Condition::Command(s) | Condition::Executable(s) => format!(
            "(which -a {} | where type == external | is-not-empty)",
            template_expr(s)
        ),
        Condition::Exists(p) => format!("({} | path exists)", template_expr(p)),
    }
}

/// The hook body for `env.nu`, which nushell runs before parsing
/// `config.nu`, so a rebuild here is visible to `config.nu`'s `source`.
/// It rebuilds when the config changed, or when the `[tool]` checks in
/// `tools.nu` find other tools than `init.nu` was built with; then nushell's
/// own answer is passed on, so a rebuild can't disagree with the check.
/// `try` covers a missing binary or `tools.nu`.
pub fn env_hook(paths: &Paths, exe: &Path, home: &Path) -> String {
    let q = |p: &Path| path_str(p, home);
    let tools = q(&paths.nu_tools());
    format!(
        "do {{\n  \
         let exe = ({exe} | path expand)\n  \
         let cfg = ({cfg} | path expand)\n  \
         let out = ({out} | path expand)\n  \
         let dir = ({dir} | path expand)\n  \
         let tools = try {{ do {{ source (if ({tools} | path exists) {{ {tools} }} else {{ null }}) }} }} catch {{ null }}\n  \
         if (not ($out | path exists)) or (($cfg | path exists) and ((ls $cfg | get 0.modified) != (ls $out | get 0.modified))) {{\n    \
         try {{ ^$exe build --config $cfg --out-dir $dir }}\n  \
         }} else if ($tools | get -o found) != ($tools | get -o built) {{\n    \
         try {{ ^$exe build --config $cfg --out-dir $dir --nu-tools ...$tools.found }}\n  \
         }}\n\
         }}\n",
        exe = q(exe),
        cfg = q(&paths.config),
        out = q(&paths.output("init.nu")),
        dir = q(&paths.out_dir),
    )
}

/// The hook body for `config.nu`. `source` resolves its path at parse time,
/// so the existence check has to be a constant expression; `source null`
/// does nothing.
pub fn config_hook(paths: &Paths, home: &Path) -> String {
    let out = path_str(&paths.output("init.nu"), home);
    format!("source (if ({out} | path exists) {{ {out} }} else {{ null }})\n")
}

/// `env.nu` and `config.nu`.
pub fn config_files() -> (PathBuf, PathBuf) {
    ask_nu().unwrap_or_else(|| {
        let dir = if env::var_os("XDG_CONFIG_HOME").is_some() {
            crate::xdg("XDG_CONFIG_HOME", ".config").join("nushell")
        } else if cfg!(target_os = "macos") {
            crate::home().join("Library/Application Support/nushell")
        } else if let Some(appdata) = env::var_os("APPDATA").filter(|_| cfg!(windows)) {
            PathBuf::from(appdata).join("nushell")
        } else {
            crate::xdg("XDG_CONFIG_HOME", ".config").join("nushell")
        };
        (dir.join("env.nu"), dir.join("config.nu"))
    })
}

/// `nu-check` prints the parse error itself; the error it then raises only
/// says that parsing failed, so it is replaced by the exit status.
pub fn syntax_check(file: &str) -> Command {
    let mut c = Command::new("nu");
    c.args([
        "-n",
        "-c",
        &format!(
            "try {{ nu-check --debug {} }} catch {{ exit 1 }}",
            quote(file)
        ),
    ]);
    c
}

/// Asks nushell itself; it knows about XDG_CONFIG_HOME and platform defaults.
fn ask_nu() -> Option<(PathBuf, PathBuf)> {
    let out = Command::new("nu")
        .args([
            "-n",
            "-c",
            "[$nu.env-path $nu.config-path] | str join (char nl)",
        ])
        .output()
        .ok()
        .filter(|o| o.status.success())?;
    let text = String::from_utf8(out.stdout).ok()?;
    let mut lines = text.lines().map(str::trim).filter(|l| !l.is_empty());
    Some((PathBuf::from(lines.next()?), PathBuf::from(lines.next()?)))
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::probe::Probe;
    use crate::shell::Checks;

    /// How the home directory is written.
    const HOME: &str = if cfg!(windows) {
        "$nu.home-dir"
    } else {
        "($env.HOME? | default '')"
    };

    /// The generated `init.nu` without its header.
    fn render_body(cfg: &str) -> String {
        render_body_with(cfg, &Checks::Now(&Probe::with_vars(&[])))
    }

    fn render_body_with(cfg: &str, checks: &Checks) -> String {
        let mut files = crate::shell::render_body_with(cfg, Shell::Nu, checks);
        assert_eq!(files.len(), 1);
        assert_eq!(files[0].0, "init.nu");
        files.remove(0).1
    }

    #[test]
    fn quoting() {
        assert_eq!(quote("plain"), "'plain'");
        assert_eq!(quote("it's"), "r#'it's'#");
        assert_eq!(quote("a'#b"), "r##'a'#b'##");
        assert_eq!(template_expr(""), "''");
        assert_eq!(template_expr("$HOME"), HOME);
        assert_eq!(template_expr("~/x"), format!("([{HOME} '/x'] | str join)"));
    }

    #[test]
    fn hook_paths() {
        let home = Path::new("/home/me");
        assert_eq!(
            path_str(Path::new("/home/me/it's $x/bin"), home),
            "r#'~/it's $x/bin'#"
        );
        assert_eq!(path_str(Path::new("/opt/x"), home), "'/opt/x'");
    }

    #[test]
    fn renders() {
        let cfg = r#"
            [env]
            EDITOR = "nvim"
            ONLY_ZSH = { zsh = "x" }
            [path]
            prepend = ["/a", "/b"]
            [aliases]
            ll = { zsh = "ls -lh", nu = "ls -l" }
        "#;
        assert_eq!(
            render_body(cfg),
            [
                "$env.EDITOR = 'nvim'",
                "$env.PATH = ($env.PATH | split row (char esep) | prepend ['/a' '/b'] | uniq)",
                "alias ll = ls -l",
            ]
            .join("\n")
        );
    }

    /// Conditions are checked at build time, against PATH as built up by
    /// the config so far: the base [path], then each applied tool's entries.
    #[test]
    fn checks_tools_when_built() {
        use crate::probe::{EXE, fixture};
        use std::fs;

        let dir = fixture("nu-tools");
        fs::create_dir(dir.join("sub")).unwrap();
        fs::copy(
            dir.join(format!("tool{EXE}")),
            dir.join(format!("sub/inner{EXE}")),
        )
        .unwrap();
        let d = dir.display().to_string();
        let probe = Probe::with_vars(&[("D", &d)]);
        let cfg = r#"
            [path]
            prepend = ["$D"]
            [tool.tool.aliases]
            t = "tool"
            [tool.missing.aliases]
            m = "missing"
            [tool.inner-too-early.aliases]
            i = "inner"
            [tool.sub]
            exists = "$D/sub"
            path.prepend = ["$D/sub"]
            [tool.inner.aliases]
            i = "inner"
            [tool.data]
            command = "$D/data"
            aliases.d = "data"
        "#;
        let d_expr = "($env.D? | default '')";
        assert_eq!(
            render_body_with(cfg, &Checks::Now(&probe)),
            [
                format!("$env.PATH = ($env.PATH | split row (char esep) | prepend [{d_expr}] | uniq)"),
                String::new(),
                "# tool: tool".into(),
                "alias t = tool".into(),
                String::new(),
                "# tool: missing (skipped: `missing` not on PATH when this file was built)".into(),
                String::new(),
                "# tool: inner-too-early (skipped: `inner-too-early` not on PATH when this file was built)".into(),
                String::new(),
                "# tool: sub".into(),
                format!("$env.PATH = ($env.PATH | split row (char esep) | prepend [([{d_expr} '/sub'] | str join)] | uniq)"),
                String::new(),
                "# tool: inner".into(),
                "alias i = inner".into(),
                String::new(),
                "# tool: data (skipped: `$D/data` not executable when this file was built)".into(),
            ]
            .join("\n")
        );
        fs::remove_dir_all(&dir).unwrap();
    }

    #[test]
    fn writes_tool_checks() {
        let cfg = Config::parse(
            r#"
            [env]
            BIN = "~/bin"
            [path]
            append = ["$BIN"]
            [tool.eza.aliases]
            ls = "eza"
            [tool.only-zsh]
            zsh.init = "x"
            [tool."it's"]
            command = ["~/x", "y"]
            exists = "/opt"
            path.prepend = ["/opt/bin"]
            "#,
        )
        .unwrap();
        let bin = "($env.BIN? | default '')";
        assert_eq!(
            tools_check(&cfg, &["eza".into()]),
            [
                "# Generated by shellsync: the [tool] checks for nushell's env.nu hook. Do not edit.",
                "mut found = []",
                &format!("$env.BIN = ([{HOME} '/bin'] | str join)"),
                &format!("$env.PATH = ($env.PATH | split row (char esep) | append [{bin}] | uniq)"),
                "if (which -a 'eza' | where type == external | is-not-empty) {",
                "  $found = ($found | append 'eza')",
                "}",
                &format!(
                    "if (which -a ([{HOME} '/x'] | str join) | where type == external | is-not-empty) \
                     and (which -a 'y' | where type == external | is-not-empty) and ('/opt' | path exists) {{"
                ),
                "  $found = ($found | append r#'it's'#)",
                "  $env.PATH = ($env.PATH | split row (char esep) | prepend ['/opt/bin'] | uniq)",
                "}",
                "{built: ['eza'], found: $found}",
                "",
            ]
            .join("\n")
        );
    }

    /// With nushell's own answer, the build uses it as given.
    #[test]
    fn uses_the_tools_nu_found() {
        let cfg = Config::parse(
            r#"
            [tool.a.aliases]
            a = "a"
            [tool.b]
            exists = "/"
            aliases.b = "b"
            [tool.c.aliases]
            c = "c"
            "#,
        )
        .unwrap();
        let found = ["c".to_string(), "a".to_string(), "not-a-tool".to_string()];
        let out = crate::shell::render(&cfg, Shell::Nu, "test", &Checks::Found(&found));
        assert_eq!(out.applied, ["a", "c"]);
        assert_eq!(
            out.files[0]
                .1
                .lines()
                .skip(2)
                .collect::<Vec<_>>()
                .join("\n"),
            [
                "",
                "# tool: a",
                "alias a = a",
                "",
                "# tool: b (skipped: not found when nu started)",
                "",
                "# tool: c",
                "alias c = c",
            ]
            .join("\n")
        );
    }

    #[test]
    fn ignores_sh_entries() {
        let cfg = r#"
            [env]
            PAGER = { sh = "less" }
            [aliases]
            ll = { sh = "ls -lh", nu = "ls -l" }
            [sh]
            init = "setopt autocd"
        "#;
        assert_eq!(render_body(cfg), "alias ll = ls -l");
    }
}
